<?php if(!defined('SW_APP')||!SW_PUBLIC){http_response_code(404);exit;} $rows=all('SELECT r.title,r.price_cents,p.number,p.payment FROM participants p JOIN raffles r ON r.id=p.raffle_id WHERE p.user_id=? ORDER BY p.created_at DESC',[$u['id']]); ?>
<p class="user-sub">Estado de los pagos de tus boletos. No se procesan pagos desde esta página.</p><?php if(!$rows):?><div class="user-empty">No tienes pagos registrados.</div><?php else:?><div class="user-table"><table><thead><tr><th>Sorteo</th><th>Boleto</th><th>Valor</th><th>Estado</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=h($r['title'])?></td><td><?=h($r['number'])?></td><td><?=money($r['price_cents'])?></td><td><?=h(state_name($r['payment']))?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?>

<?php $refunds=all('SELECT r.title,p.number,f.amount_cents FROM raffle_refund_reviews f JOIN participants p ON p.id=f.participant_id JOIN raffles r ON r.id=f.raffle_id WHERE p.user_id=?',[$u['id']]);if($refunds):?><h2>Devoluciones pendientes de revisión</h2><div class="user-table"><table><thead><tr><th>Sorteo</th><th>Número</th><th>Importe pendiente</th></tr></thead><tbody><?php foreach($refunds as $f):?><tr><td><?=h($f['title'])?></td><td><?=h($f['number'])?></td><td><?=money($f['amount_cents'])?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?>